/**
 * Engine parity suite.
 *
 * The TypeScript engine is a port of the Python reference engine. This
 * suite asserts they produce byte-identical output on a fixed fixture
 * set generated by `python scripts/generate_golden_fixtures.py`.
 *
 * If the fixtures file is missing, the suite fails loudly rather than
 * silently skipping — a port without parity evidence is not a port.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import {
  analyzeOwnerLoad,
  detectCrossTeamFriction,
  detectSystemicRisks,
  generateMeetingBrief,
  getOrgPulseEnhanced,
} from "@/lib/intelligence";
import { extractProfileKeywords, profileRelevance } from "@/lib/persona";
import { formatMoney, impactLine } from "@/lib/format";
import {
  computeAllFlags,
  getAtRisk,
  getAttentionQueue,
  getCounts,
  getDecisionQueue,
  getExecutiveAttentionQueue,
  parseDate,
  parseReferenceDate,
  rankAttention,
  scoreBand,
} from "@/lib/rule-engine";
import type { ScoredTask, Task } from "@/lib/types";

const FIXTURE_PATH = join(__dirname, "fixtures", "engine-golden.json");

interface Golden {
  referenceDate: string;
  rows: Array<Record<string, unknown>>;
  attention: Array<Record<string, unknown>>;
  atRisk: Array<Record<string, unknown>>;
  decisions: Array<Record<string, unknown>>;
  decisionDetails: Array<Record<string, unknown>>;
  orgPulse: Array<Record<string, unknown>>;
  counts: Record<string, number>;
  friction: Array<Record<string, unknown>>;
  ownerLoads: Array<Record<string, unknown>>;
  systemicRisks: Array<Record<string, unknown>>;
  blockedSummary: Record<string, number>;
  meetingBrief: {
    summary: Record<string, number>;
    decisionCount: number;
    criticalRiskCount: number;
    frictionCount: number;
    systemicRiskCount: number;
  };
}

const golden: Golden = JSON.parse(readFileSync(FIXTURE_PATH, "utf-8"));
// The fixture timestamp is naive; treat it as UTC so the reference and
// the task dates share one frame of reference.
const REFERENCE_MS = parseReferenceDate(golden.referenceDate);

/** Rebuild the raw task list from the golden rows. */
function buildTasks(): Task[] {
  return golden.rows.map((row) => ({
    Task_ID: String(row.Task_ID),
    Task: String(row.Task),
    Project: String(row.Project),
    Department: String(row.Department),
    Owner: String(row.Owner),
    Owner_Role: String(row.Owner_Role),
    Status: String(row.Status) as Task["Status"],
    Priority: String(row.Priority) as Task["Priority"],
    Start_Date: (row.Start_Date as string) ?? null,
    Due_Date: (row.Due_Date as string) ?? null,
    Completed_Date: (row.Completed_Date as string) ?? null,
    Impact: String(row.Impact) as Task["Impact"],
    Impact_Value: Number(row.Impact_Value ?? 0),
    Blocker: String(row.Blocker ?? ""),
    Dependency: String(row.Dependency ?? ""),
    Blocker_Owner: String(row.Blocker_Owner ?? ""),
    Last_Updated: (row.Last_Updated as string) ?? null,
    Executive_Decision_Required: row.Executive_Decision_Required === true,
    Decision_By: (row.Decision_By as string) ?? null,
    Decision_Requested: String(row.Decision_Requested ?? ""),
    Source_URL: String(row.Source_URL ?? ""),
    Notes: String(row.Notes ?? ""),
  }));
}

const scored: ScoredTask[] = computeAllFlags(buildTasks(), REFERENCE_MS);

describe("engine parity with the Python reference", () => {
  it("uses a fixed reference date so results never drift", () => {
    expect(golden.referenceDate).toBe("2026-09-28T10:30:00");
  });

  it("produces identical per-task flags, scores and bands", () => {
    expect(scored.length).toBe(golden.rows.length);
    for (let i = 0; i < golden.rows.length; i += 1) {
      const expected = golden.rows[i];
      const actual = scored[i];
      const label = `row ${i} (${actual.Task_ID})`;

      expect(actual.overdue, `${label} overdue`).toBe(expected.overdue);
      expect(actual.at_risk, `${label} at_risk`).toBe(expected.at_risk);
      expect(actual.blocked, `${label} blocked`).toBe(expected.blocked);
      expect(actual.stale, `${label} stale`).toBe(expected.stale);
      expect(actual.decision_required, `${label} decision_required`).toBe(
        expected.decision_required,
      );
      expect(actual.dependency_risk, `${label} dependency_risk`).toBe(
        expected.dependency_risk,
      );
      expect(actual.high_impact, `${label} high_impact`).toBe(
        expected.high_impact,
      );
      expect(actual.attention_score, `${label} attention_score`).toBe(
        expected.attention_score,
      );
      expect(actual.score_band, `${label} score_band`).toBe(expected.score_band);
      expect(actual.reason_codes.join("; "), `${label} reason_codes`).toBe(
        expected.reason_codes,
      );
    }
  });

  it("produces identical attention queue", () => {
    const queue = getExecutiveAttentionQueue(scored, 7, "High");
    expect(queue.map((task) => task.Task_ID)).toEqual(
      golden.attention.map((row) => row.Task_ID),
    );
  });

  it("produces identical at-risk view", () => {
    const atRisk = getAtRisk(scored);
    expect(atRisk.map((task) => task.Task_ID)).toEqual(
      golden.atRisk.map((row) => row.Task_ID),
    );
  });

  it("produces identical decision queue", () => {
    const decisions = getDecisionQueue(scored);
    expect(decisions.map((task) => task.Task_ID)).toEqual(
      golden.decisions.map((row) => row.Task_ID),
    );
  });

  it("produces identical decision urgency and impact context", async () => {
    const { getDecisionQueueDetailed } = await import("@/lib/intelligence");
    const detailed = getDecisionQueueDetailed(scored, REFERENCE_MS);
    expect(detailed.length).toBe(golden.decisionDetails.length);
    for (let i = 0; i < detailed.length; i += 1) {
      const expected = golden.decisionDetails[i];
      const actual = detailed[i] as unknown as Record<string, string>;
      const label = `decision ${actual.Task_ID}`;
      expect(actual.decision_urgency, label).toBe(expected.decision_urgency);
      expect(actual.impact_context, label).toBe(expected.impact_context);
    }
  });

  it("produces identical counts", () => {
    const counts = getCounts(scored);
    expect(counts.total).toBe(golden.counts.total);
    expect(counts.open).toBe(golden.counts.open);
    expect(counts.attention).toBe(golden.counts.attention);
    expect(counts.decisions).toBe(golden.counts.decisions);
    expect(counts.blocked).toBe(golden.counts.blocked);
    expect(counts.atRisk).toBe(golden.counts.atRisk);
    expect(counts.stale).toBe(golden.counts.stale);
    expect(counts.overdue).toBe(golden.counts.overdue);
    expect(counts.critical).toBe(golden.counts.critical);
  });

  it("produces identical org pulse", () => {
    const org = getOrgPulseEnhanced(scored);
    expect(org.length).toBe(golden.orgPulse.length);
    for (let i = 0; i < org.length; i += 1) {
      const expected = golden.orgPulse[i];
      const actual = org[i];
      const label = `dept ${actual.Department}`;

      expect(actual.Department, label).toBe(expected.Department);
      expect(actual.Open, `${label} Open`).toBe(expected.Open);
      expect(actual.Overdue, `${label} Overdue`).toBe(expected.Overdue);
      expect(actual.Blocked, `${label} Blocked`).toBe(expected.Blocked);
      expect(actual.At_Risk, `${label} At_Risk`).toBe(expected.At_Risk);
      expect(actual.High_Impact, `${label} High_Impact`).toBe(
        expected.High_Impact,
      );
      expect(actual.Stale, `${label} Stale`).toBe(expected.Stale);
      expect(actual.Decisions, `${label} Decisions`).toBe(expected.Decisions);
      expect(actual.Completion_Rate, `${label} Completion_Rate`).toBe(
        expected.Completion_Rate,
      );
      expect(actual.Risk_Score, `${label} Risk_Score`).toBe(expected.Risk_Score);
    }
  });

  it("produces identical cross-team friction", () => {
    const friction = detectCrossTeamFriction(scored, REFERENCE_MS);
    expect(friction.length).toBe(golden.friction.length);
    for (let i = 0; i < friction.length; i += 1) {
      const expected = golden.friction[i];
      const actual = friction[i];
      const label = `friction ${i} (${actual.blocker_owner})`;

      expect(actual.blocker_owner, label).toBe(expected.blockerOwner);
      expect(actual.blocker_dept, label).toBe(expected.blockerDept);
      expect(actual.blocked_count, label).toBe(expected.blockedCount);
      expect(actual.total_impact_value, label).toBe(expected.totalImpact);
      expect(actual.max_days_blocked, label).toBe(expected.maxDaysBlocked);
      expect(actual.severity, label).toBe(expected.severity);
      expect(
        actual.blocked_tasks.map((task) => task.task_id).sort(),
        `${label} blocked tasks`,
      ).toEqual([...(expected.blockedTaskIds as string[])].sort());
    }
  });

  it("produces identical owner load analysis", () => {
    const loads = analyzeOwnerLoad(scored);
    expect(loads.length).toBe(golden.ownerLoads.length);
    for (let i = 0; i < loads.length; i += 1) {
      const expected = golden.ownerLoads[i];
      const actual = loads[i];
      const label = `owner ${actual.owner}`;

      expect(actual.owner, label).toBe(expected.owner);
      expect(actual.department, label).toBe(expected.department);
      expect(actual.total_open, label).toBe(expected.totalOpen);
      expect(actual.overdue, label).toBe(expected.overdue);
      expect(actual.blocked, label).toBe(expected.blocked);
      expect(actual.high_impact, label).toBe(expected.highImpact);
      expect(actual.decisions_required, label).toBe(expected.decisionsRequired);
      expect(actual.avg_attention_score, label).toBe(
        expected.avgAttentionScore,
      );
      expect(actual.load_level, label).toBe(expected.loadLevel);
    }
  });

  it("produces identical systemic risks", () => {
    const risks = detectSystemicRisks(scored);
    expect(risks.length).toBe(golden.systemicRisks.length);
    for (let i = 0; i < risks.length; i += 1) {
      const expected = golden.systemicRisks[i];
      const actual = risks[i];
      const label = `risk ${i} (${actual.pattern_type})`;

      expect(actual.pattern_type, label).toBe(expected.type);
      expect(actual.description, label).toBe(expected.description);
      expect(actual.severity, label).toBe(expected.severity);
      expect(actual.recommendation, label).toBe(expected.recommendation);
      expect(actual.affected_items.length, label).toBe(expected.affectedCount);
    }
  });

  it("produces an identical meeting brief summary", () => {
    const brief = generateMeetingBrief(scored, {
      meetingName: "Q3 Board Review",
      referenceMs: REFERENCE_MS,
    });

    expect(brief.summary.total_open).toBe(golden.meetingBrief.summary.total_open);
    expect(brief.summary.decisions_required).toBe(
      golden.meetingBrief.summary.decisions_required,
    );
    expect(brief.summary.critical_risk).toBe(
      golden.meetingBrief.summary.critical_risk,
    );
    expect(brief.summary.high_risk).toBe(golden.meetingBrief.summary.high_risk);
    expect(brief.summary.blocked).toBe(golden.meetingBrief.summary.blocked);
    expect(brief.summary.overdue).toBe(golden.meetingBrief.summary.overdue);
    expect(brief.summary.friction_points).toBe(
      golden.meetingBrief.summary.friction_points,
    );
    expect(brief.summary.systemic_risks).toBe(
      golden.meetingBrief.summary.systemic_risks,
    );
    expect(brief.summary.overloaded_owners).toBe(
      golden.meetingBrief.summary.overloaded_owners,
    );
  });
});

describe("rule engine contract", () => {
  it("never flags a task due today as overdue", () => {
    const today = new Date(REFERENCE_MS);
    const dueToday = today.toISOString().slice(0, 10);
    const task: Task = {
      ...buildTasks()[0],
      Task_ID: "TODAY-1",
      Due_Date: dueToday,
      Last_Updated: today.toISOString().slice(0, 16).replace("T", " "),
      Status: "In Progress",
      Blocker: "",
      Impact: "Low",
      Executive_Decision_Required: false,
    };
    const [scoredTask] = computeAllFlags([task], REFERENCE_MS);
    expect(scoredTask.overdue).toBe(false);
    expect(scoredTask.at_risk).toBe(true);
  });

  it("treats a task due 48h+ as stale, 48h exactly as fresh", () => {
    const base = buildTasks()[0];
    const stale = {
      ...base,
      Task_ID: "STALE-1",
      Last_Updated: new Date(REFERENCE_MS - 49 * 3_600_000)
        .toISOString()
        .slice(0, 16)
        .replace("T", " "),
    };
    const fresh = {
      ...base,
      Task_ID: "STALE-2",
      Last_Updated: new Date(REFERENCE_MS - 48 * 3_600_000)
        .toISOString()
        .slice(0, 16)
        .replace("T", " "),
    };
    const [staleTask, freshTask] = computeAllFlags([stale, fresh], REFERENCE_MS);
    expect(staleTask.stale).toBe(true);
    expect(freshTask.stale).toBe(false);
  });

  it("maps scores to the documented bands", () => {
    expect(scoreBand(10)).toBe("Critical");
    expect(scoreBand(13)).toBe("Critical");
    expect(scoreBand(7)).toBe("High");
    expect(scoreBand(9)).toBe("High");
    expect(scoreBand(4)).toBe("Watch");
    expect(scoreBand(6)).toBe("Watch");
    expect(scoreBand(3)).toBe("Normal");
    expect(scoreBand(0)).toBe("Normal");
  });

  it("caps the attention queue without capping the count", () => {
    expect(getAttentionQueue(scored, 7).length).toBeLessThanOrEqual(7);
    expect(getCounts(scored).attention).toBeGreaterThanOrEqual(
      getAttentionQueue(scored, 7).length,
    );
  });

  it("parses dates without timezone drift", () => {
    expect(parseDate("2026-09-29")).toBe(Date.UTC(2026, 8, 29));
    expect(parseDate("2026-09-27 14:30")).toBe(Date.UTC(2026, 8, 27, 14, 30));
    expect(parseDate("")).toBeNull();
    expect(parseDate(null)).toBeNull();
  });

  it("keeps ranking stable for identical scores", () => {
    const ranked = rankAttention(scored);
    const ids = ranked.map((task) => task.Task_ID);
    expect(new Set(ids).size).toBe(ids.length);
  });
});

describe("focus profile parity", () => {
  it("extracts the same keywords as the Python reference", () => {
    const keywords = extractProfileKeywords(
      "brand launches, partnerships, customer escalations",
    );
    expect(keywords).toContain("brand");
    expect(keywords).toContain("launches");
    expect(keywords).toContain("partnerships");
    expect(keywords).toContain("customer");
    expect(keywords).toContain("escalations");
  });

  it("drops stopwords", () => {
    const keywords = extractProfileKeywords("I want the brand and the teams");
    expect(keywords).toContain("brand");
    expect(keywords).not.toContain("and");
    expect(keywords).not.toContain("the");
  });

  it("weights the title above other fields", () => {
    const task = buildTasks()[0];
    const inTitle = profileRelevance(
      { ...task, Task: "Brand launch campaign", Project: "Other" },
      ["brand"],
    );
    const inNotes = profileRelevance(
      { ...task, Task: "Unrelated", Project: "Other", Notes: "brand" },
      ["brand"],
    );
    expect(inTitle.score).toBeGreaterThan(inNotes.score);
  });

  it("matches prefixes", () => {
    const task = buildTasks()[0];
    const result = profileRelevance(
      { ...task, Task: "Launch the rebrand project" },
      ["launch"],
    );
    expect(result.score).toBeGreaterThan(0);
    expect(result.matched).toContain("launch");
  });

  it("matches a keyword that extends a token", () => {
    // "design" should match "designed" and "designing".
    const task = buildTasks()[0];
    expect(
      profileRelevance({ ...task, Task: "New homepage design" }, ["design"]).score,
    ).toBeGreaterThan(0);
  });

  it("does NOT match a shorter token that shares the keyword's prefix", () => {
    // "marketing" must not match "market" — otherwise a task titled
    // "India market launch" lands in a Marketing exec's focus queue.
    const task = buildTasks()[0];
    const result = profileRelevance(
      { ...task, Task: "India market launch partner approval" },
      ["marketing"],
    );
    expect(result.score).toBe(0);
    expect(result.matched).toEqual([]);
  });

  it("still matches a keyword inside a longer word", () => {
    const task = buildTasks()[0];
    const result = profileRelevance(
      { ...task, Task: "Full rebranding programme" },
      ["brand"],
    );
    expect(result.score).toBeGreaterThan(0);
  });
});
